type Story = StoryObj;

export const Playground: StoryObj<{
  disabled: boolean;
  multiple: boolean;
  searchable: boolean;
  size: "sm" | "default";
}> = {
  argTypes: {
    disabled: { control: "boolean" },
    multiple: { control: "boolean" },
    searchable: { control: "boolean" },
    size: { control: "select", options: ["sm", "default"] },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import {
  Cascader,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
  CascaderValue,
} from "@/registry/erbium/ui/cascader";

import { regions } from "../examples/cascader-data";

export const defaultProps = {
  disabled: false,
  multiple: false,
  searchable: true,
  size: "default",
} satisfies {
  disabled: boolean;
  multiple: boolean;
  searchable: boolean;
  size: "sm" | "default";
};

export default function CascaderPlaygroundExample(
  args: {
    disabled: boolean;
    multiple: boolean;
    searchable: boolean;
    size: "sm" | "default";
  } = defaultProps,
) {
  const content = (
    <CascaderContent>
      {args.searchable ? (
        <>
          <CascaderSearch placeholder="Search places…" />
          <CascaderEmpty>No places found.</CascaderEmpty>
        </>
      ) : null}
      <CascaderList />
    </CascaderContent>
  );

  const trigger = (
    <CascaderTrigger aria-label="City" size={args.size} className="w-72">
      <CascaderValue placeholder={args.multiple ? "Choose cities" : "Choose a city"} />
    </CascaderTrigger>
  );

  // Remount when the mode or search changes so each starts from an empty value and fresh levels.
  return args.multiple ? (
    <Cascader
      key={`multiple-${String(args.searchable)}`}
      multiple
      items={regions}
      searchable={args.searchable}
      disabled={args.disabled}
    >
      {trigger}
      {content}
    </Cascader>
  ) : (
    <Cascader
      key={`single-${String(args.searchable)}`}
      items={regions}
      searchable={args.searchable}
      disabled={args.disabled}
    >
      {trigger}
      {content}
    </Cascader>
  );
}
" },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "A city picker three levels deep. A continent opens its countries in place and a country its cities, with a back button in the search. The popup reopens on the level of the chosen city, and the trigger shows its whole path. Type in the search to find a place at any depth below the open level." },
      source: { code: "import {
  Cascader,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
  CascaderValue,
} from "@/registry/erbium/ui/cascader";
import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";

import { regions } from "./cascader-data";

export default function CascaderExample() {
  return (
    <Field className="w-72">
      <FieldLabel htmlFor="cascader-demo">Office</FieldLabel>
      <Cascader searchable items={regions} defaultValue="tokyo">
        <CascaderTrigger id="cascader-demo" className="w-full">
          <CascaderValue placeholder="Choose a city" />
        </CascaderTrigger>
        <CascaderContent>
          <CascaderSearch placeholder="Search places…" />
          <CascaderEmpty>No places found.</CascaderEmpty>
          <CascaderList />
        </CascaderContent>
      </Cascader>
      <FieldDescription>Open a continent, then a country, then pick a city.</FieldDescription>
    </Field>
  );
}
" },
    },
  },
  render: OverviewExample,
};

export const Controlled: Story = {
  parameters: {
    docs: {
      description: { story: "Pass `value` and `onValueChange`. The second argument of `onValueChange` carries the picked node and its `path`, root first, so you do not have to look the node up again." },
      source: { code: "import * as React from "react";

import {
  Cascader,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
  CascaderValue,
} from "@/registry/erbium/ui/cascader";

import { regions } from "../examples/cascader-data";

export default function CascaderControlledExample() {
  const [value, setValue] = React.useState<string | null>(null);
  const [path, setPath] = React.useState<string[]>([]);

  return (
    <div className="flex w-72 flex-col gap-related">
      <Cascader
        searchable
        items={regions}
        value={value}
        onValueChange={(next, details) => {
          setValue(next);
          setPath(details.path.map((node) => node.label));
        }}
      >
        <CascaderTrigger aria-label="City" className="w-full">
          <CascaderValue placeholder="Choose a city" />
        </CascaderTrigger>
        <CascaderContent>
          <CascaderSearch placeholder="Search places…" />
          <CascaderEmpty>No places found.</CascaderEmpty>
          <CascaderList />
        </CascaderContent>
      </Cascader>
      <output className="text-caption text-muted-foreground">
        {value === null ? "No city selected." : `value="${value}" · ${path.join(" › ")}`}
      </output>
    </div>
  );
}
" },
    },
  },
  render: ControlledExample,
};

export const Multiple: Story = {
  parameters: {
    docs: {
      description: { story: "With `multiple`, leaves are checkbox items and the popup stays open while you pick. A level shows how many of its leaves are selected in place of its option count. `CascaderClear` adds a footer that clears the selection." },
      source: { code: "import * as React from "react";

import {
  Cascader,
  CascaderClear,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
  CascaderValue,
} from "@/registry/erbium/ui/cascader";

import { permissions } from "../examples/cascader-permissions";

export default function CascaderMultipleExample() {
  const [value, setValue] = React.useState<string[]>(["members.view", "projects.view"]);

  return (
    <div className="flex w-72 flex-col gap-related">
      <Cascader multiple searchable items={permissions} value={value} onValueChange={setValue}>
        <CascaderTrigger aria-label="Permissions" className="w-full">
          <CascaderValue placeholder="Select permissions" />
        </CascaderTrigger>
        <CascaderContent>
          <CascaderSearch />
          <CascaderEmpty>No permissions found.</CascaderEmpty>
          <CascaderList />
          <CascaderClear />
        </CascaderContent>
      </Cascader>
      <output className="text-caption text-muted-foreground">
        {value.length === 0 ? "No permissions." : value.join(", ")}
      </output>
    </div>
  );
}
" },
    },
  },
  render: MultipleExample,
};

export const Custom: Story = {
  parameters: {
    docs: {
      description: { story: "Give nodes an `icon` and a `description` for richer rows, and pass a function to `CascaderValue` to render the selection your own way. It receives the path of each selected leaf." },
      source: { code: "import {
  Cascader,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
  CascaderValue,
} from "@/registry/erbium/ui/cascader";
import type { CascaderNode } from "@/registry/erbium/ui/cascader";
import { Icon } from "@/registry/erbium/ui/icon";

const attributes: CascaderNode[] = [
  {
    value: "record-id",
    label: "Record ID",
    icon: <Icon name="tag-01" aria-hidden="true" />,
    description: "Unique identifier",
  },
  {
