export const Form: Story = {
  parameters: {
    docs: {
      description: { story: "Inside `field.Field`, the trigger shows the invalid state and a rejected submit shakes it. Touch the field when the popup closes, since focus moves to the search while it is open." },
      source: { code: "import * as React from "react";

import {
  Cascader,
  CascaderContent,
  CascaderEmpty,
  CascaderList,
  CascaderSearch,
  CascaderTrigger,
  CascaderValue,
} from "@/registry/erbium/ui/cascader";
